    chapters = {
        {
            chapter = "The True Masters",
            faction = "Alliance",
            summary = "Black dragonkin are gathering in the Burning Steppes, uncomfortably close to Morgan's Vigil. Helendis Riverhorn at the Vigil wants their numbers thinned, from the smallest broodling right up to a drake.",
            recap = "Morgan's Vigil had a dragonkin problem, and for about an afternoon I was the solution. Then the letters started. The Vigil wrote to the magistrate in Lakeshire, the magistrate wrote to Stormwind, and I carried every one of them up and down the kingdom like a well-armed pigeon.\n\nIn the keep, Lady Katrana Prestor had a little advice for me before the Highlord gave his answer. The answer was no. A very polite no, on very good paper. The magistrate read it twice and stopped being polite himself.\n\nWhich is how I ended up in a cave up north of the Ruins of Thaurissan, listening to a fellow called Ragged John tell me what had become of a marshal named Windsor. The ragged part, I'll say, was earned.",
            quests = {
                { id = 4182, name = "Dragonkin Menace", npc = "Helendis Riverhorn" },
                { id = 4183, name = "The True Masters", displayName = "To Lakeshire", npc = "Helendis Riverhorn" },
                { id = 4184, name = "The True Masters", displayName = "To Stormwind", npc = "Magistrate Solomon" },
                { id = 4185, name = "The True Masters", displayName = "Back to Lakeshire", npc = "Highlord Bolvar Fordragon" },
                { id = 4186, name = "The True Masters", displayName = "To Morgan's Vigil", npc = "Highlord Bolvar Fordragon" },
                { id = 4223, name = "The True Masters", displayName = "Ragged John's Tale", npc = "Magistrate Solomon" },
                { id = 4224, name = "The True Masters", displayName = "Return to Maxwell", npc = "Marshal Maxwell" },
            },
        },
        {
            chapter = "Marshal Windsor",
            faction = "Alliance",
            summary = "Ragged John's tale ended with Marshal Windsor dragged off to a prison. Marshal Maxwell at Morgan's Vigil wants to know what became of him, and the trail leads into Blackrock Depths, under Blackrock Mountain.",
            recap = "Ragged John's tale ended in a Dark Iron prison, so down into Blackrock Depths I went, and there was Marshal Windsor in a cell, finished. They'd taken his proof, and with it whatever had been holding him up. He sent me back to give Maxwell the bad news.\n\nHe'd have stayed finished, too, if a crumpled note hadn't turned up in the Depths. One look at it and the marshal was back. His papers were with a golem lord and a general down there, and neither of them wanted to give anything back. I didn't take it personally.\n\nOnce Windsor had his papers, he wanted his gear and his friends out of their cells, in that order. Blackrock Depths had opinions about that. We got both anyway.",
            quests = {
                { id = 4241, name = "Marshal Windsor", npc = "Marshal Maxwell" },
                { id = 4242, name = "Abandoned Hope", npc = "Marshal Windsor" },
                { id = 4264, name = "A Crumpled Up Note", npc = "A Crumpled Up Note" },
                { id = 4282, name = "A Shred of Hope", npc = "Marshal Windsor" },
                { id = 4322, name = "Jail Break!", npc = "Marshal Windsor" },
            },
        },
        {
            chapter = "The Great Masquerade",
            faction = "Alliance",
            summary = "Marshal Maxwell at Morgan's Vigil has word from Marshal Windsor: he's bound for Stormwind and wants you there when he arrives. Go to the city gates and find Squire Rowe, who will let Windsor know you've come.",
            recap = "A squire at the gates of Stormwind had one job that day: let Marshal Windsor know I'd come. Then Windsor arrived, and we walked into the city together, and I kept him alive all the way up to the keep. That took some doing.\n\nIn the throne room he faced Lady Katrana Prestor, the most trusted voice at court, and called her by her real name. Onyxia. The whole court got a good look at what had been whispering in the Highlord's ear all this time.\n\nShe killed him for it, right there. But the secret was out, and there's no spell in the world that puts that back.\n\nI never got to buy him a drink. So this one's his.",
            quests = {
                { id = 6402, name = "Stormwind Rendezvous", npc = "Marshal Maxwell" },
                { id = 6403, altIds = { 99435 }, name = "The Great Masquerade", npc = "Reginald Windsor" },
            },
        },
        {
            chapter = "The Drakefire Amulet",
            faction = "Alliance",
            summary = "Highlord Bolvar Fordragon in Stormwind Keep hands you a fragment of the Dragon's Eye. Someone out there can restore its power. That is the whole of what anyone knows about them, so the search may take a while.",
            recap = "Afterward the Highlord handed me a fragment of something called the Dragon's Eye and told me to find someone who could restore its power. Who? Nobody knew. Where? Nobody knew that either. All anyone could say for certain was that such a someone existed. I've had better directions from drunks.\n\nThe someone turned out to be Haleh, up at Mazthoril in Winterspring, and Haleh's price for the Drakefire Amulet was the blood of the black dragonflight's champion. General Drakkisath, on his throne at the top of Blackrock Spire.\n\nI went up with friends. Drakkisath had a great many guards and a bad temper, and by the end a lot less blood. Haleh made the amulet. Onyxia keeps a lair down in Dustwallow Marsh, and now I can let myself in.",
            quests = {
                { id = 6501, name = "The Dragon's Eye", npc = "Highlord Bolvar Fordragon" },
                { id = 6502, name = "Drakefire Amulet", npc = "Haleh" },
                { id = 5001, name = "Bijou's Belongings", npc = "Bijou", optional = true },
                { id = 5002, name = "Message to Maxwell", npc = "Bijou", optional = true },
                { id = 5081, name = "Maxwell's Mission", npc = "Marshal Maxwell", optional = true, recap = "In the lower Spire a goblin named Bijou, who doesn't usually deal with my sort, traded me a map for her lost belongings. Marshal Maxwell picked three names off it, a war master, a highlord and an overlord, and sent me back to cross them out. That bought the Alliance precious, precious time, he said, precious enough to say twice." },
                { id = 5089, name = "General Drakkisath's Command", location = "Lower Blackrock Spire", optional = true },
                { id = 5102, name = "General Drakkisath's Demise", npc = "Marshal Maxwell", optional = true, recap = "A dead serpent in the lower Spire turned out to be carrying a letter: General Drakkisath's own orders, mostly about protocol. Marshal Maxwell read it, said the plot thickened, and sent me back up to destroy the general. I was going anyway, but I let him think it was his idea." },
                { id = 7761, name = "Blackhand's Command", location = "Blackrock Mountain, near Blackrock Spire", optional = true, recap = "On the way up to the Spire, a quartermaster was carrying a letter from Rend Blackhand, mostly insults, saying only those with the Mark of Drakkisath could use the Orb of Command into Blackwing Lair, and the general guards the brand himself. With the general past guarding anything, I pressed my hand to the smoldering brand. I didn't flinch, much." },
                { id = 4701, name = "Put Her Down", npc = "Helendis Riverhorn", optional = true, recap = "Helendis Riverhorn at the Vigil had noticed that killing worgs never left fewer worgs, and sent me into the Spire to find out why. The why was Halycon, their gigantic den mother, and I put her down. Helendis told me not to dwell on her suffering, which I hadn't planned to." },
                { id = 4766, name = "Mayara Brightwing", npc = "Count Remington Ridgewell", optional = true, breadcrumbFor = 4764 },
                { id = 4764, name = "Doomrigger's Clasp", npc = "Mayara Brightwing", optional = true },
                { id = 4765, name = "Delivery to Ridgewell", npc = "Mayara Brightwing", optional = true, recap = "Mayara Brightwing hunts art for Count Remington Ridgewell's family museum and had found a piece in the Spire: Doomrigger's Clasp, a jeweled relic said to make dwarves weep. I dug it out of the old Hall of Fortune and took it to the count in a crate. His gratitude, I was told, is nigh worth a king's ransom, and nigh is doing a lot of work there." },
                { id = 4742, name = "Seal of Ascension", npc = "Vaelan", optional = true },
                { id = 4743, name = "Seal of Ascension", npc = "Vaelan", optional = true, recap = "Vaelan, in the lower Spire, wanted a gemstone from each of three generals and an old seal to set them in. Forging it took black dragonfire, so I wore Emberstrife down in the Wyrmbog and borrowed his mind just long enough to make him breathe on it. That seal is the key to the upper Spire, and not many keys get made that way." },
                { id = 4907, name = "Tinkee Steamboil", npc = "Felnok Steelspring", optional = true, breadcrumbFor = 4734 },
                { id = 4734, name = "Egg Freezing", npc = "Tinkee Steamboil", optional = true },
                { id = 4735, name = "Egg Collection", npc = "Tinkee Steamboil", optional = true, recap = "Tinkee Steamboil at Flame Crest had built a gadget for freezing black dragon eggs solid and needed someone to try it in the Rookery atop the Spire. It worked, so I went back up and collected eight. Freeze them first, Tinkee said, or they might hatch before you get them, which is advice you only need once." },
                { id = 4729, name = "Kibler's Exotic Pets", npc = "Kibler", optional = true, recap = "Kibler at Flame Crest tames exotic beasts for rich clients, and wanted a Bloodaxe worg pup out of the Spire before it grew too old to train. I carried one back in a cage, and Kibler gave me a tame one of my own. It is very ferocious and about the size of a boot." },
                { id = 4862, name = "En-Ay-Es-Tee-Why", npc = "Kibler", optional = true, recap = "Kibler's helper had gone into the Spire for spider eggs weeks before and still wasn't back, so I fetched fifteen myself. Some people, Kibler says, will pay good gold for the most vile of domesticated beasts. I got one free, a little Smolderweb spider, along with a warning not to get bitten." },
                { id = 4866, name = "Mother's Milk", npc = "Ragged John", optional = true, recap = "Ragged John wanted Mother Smolderweb's venom, and not in a jar: he wanted it live, in my veins. So I let the biggest spider in the Spire bite me, walked back feeling awful, and he milked it out of me for the best ale he'd ever brewed. You thought I wanted it for poison, he said, crazy kids." },
                { id = 4867, name = "Urok Doomhowl", npc = "Warosh", optional = true, recap = "Urok Doomhowl had cursed Warosh mute, so all Warosh could do was hand me a scroll that came down to: get my mojo. I got the mojo, and with a voice again Warosh told me I was a fool to think I'd reach the top of the Spire, but that my bravery was beyond question. I've had warmer thanks, and worse." },
                { id = 5160, name = "The Matron Protectorate", npc = "Awbee", optional = true, recap = "Deep in the Spire, Awbee gave me a scale and sent me to Winterspring, where you stand on a cobalt rune in the caves of Mazthoril and end up in front of Haleh. Haleh scried what Awbee had seen in that doomed place. Dragons, I learned, are forbidden to meddle in mortal affairs, unless one of their own starts it." },
                { id = 5047, name = "Pip Quickwit, At Your Service!", npc = "Pip Quickwit", optional = true, recap = "We skinned the Beast in the upper Spire, and out climbed a gnome named Pip Quickwit, in a suit, delighted with how the suit had held up. Pip sent me to Malyfous Darkhammer in Everlook with the news and a glowing lump of the Beast's insides. Malyfous asked if Pip was alive, if the suit worked, and then mostly about the lump." },
                { id = 5127, name = "The Demon Forge", npc = "Lorax", optional = true, recap = "Lorax, out in the snows of Winterspring, had bought the soul of a Spire smith named Goraluk Anvilcrack and sent me to collect it with a fel-soaked pike. Goraluk died, the pike drank him up, and I brought back the breastplate he'd stolen too. Lorax thanked me in rhyme, which somehow made it worse." },
            },
        },
        {
            chapter = "For the Horde",
            faction = "Horde",
            summary = "Warlord Goretooth in Kargath, out in the Badlands, has three names in Lower Blackrock Spire and wants every one of them dead. Whatever papers they're keeping, the warlord wants those brought back too.",
            recap = "Warlord Goretooth in Kargath doesn't give orders so much as read out a list. Three names in Lower Blackrock Spire, all to be dead, and whatever papers they were sitting on brought back. What was in those papers got me sent straight to Orgrimmar.\n\nThe Warchief's answer was short. Go to Blackrock Spire. Kill Rend Blackhand. Bring back his head. Rend called himself a warchief, and Orgrimmar only has room for one.\n\nSo I went, and Rend's head came home with me. Then Thrall sat me down and told me what the wind had been carrying, and none of it was good. Dragons, mostly. Black ones.",
            quests = {
                { id = 4903, name = "Warlord's Command", npc = "Warlord Goretooth" },
                { id = 98325, name = "Blood and Thunder", npc = "Warlord Goretooth", optional = true, gameVersions = { forever = true }, recap = "Warlord Goretooth was recruiting in Kargath for the Expeditionary Force and wanted the Horde's best, with a speech to match. The cowards were invited to leave. I stayed, and got a grin and my orders, which from Goretooth is about as warm as it gets." },
                { id = 4941, name = "Eitrigg's Wisdom", npc = "Warlord Goretooth" },
                { id = 4974, name = "For The Horde!", npc = "Thrall" },
                { id = 6566, name = "What the Wind Carries", npc = "Thrall" },
            },
        },
        {
            chapter = "Rexxar's Testament",
            faction = "Horde",
            summary = "Thrall, in Grommash Hold, wants you to find Rexxar, the Champion of the Horde. Rexxar walks the paths of Desolace somewhere between Stonetalon and Feralas and doesn't wait for visitors. Expect to walk.",
            recap = "Finding Rexxar is a job in itself. He walks the roads of Desolace somewhere between Stonetalon and Feralas, which is a great deal of road. I walked most of it before I caught him walking the rest.\n\nHe sent me with his testament to Myranda the Hag in the Western Plaguelands. Myranda deals in deception, and deception has ingredients. This batch needed twenty eyes off the black dragonspawn in Blackrock Spire. I didn't ask why eyes. Myranda didn't say.\n\nWhat came back was an amulet. Wear it into Emberstrife's den in Dustwallow Marsh, and a black dragon looks at you and sees family. I stood there in somebody else's scales making polite conversation with a dragon. Still one of my better performances.",
            quests = {
                { id = 6567, name = "The Champion of the Horde", npc = "Thrall" },
                { id = 6568, name = "The Testament of Rexxar", displayName = "Mistress of Deception", npc = "Rexxar" },
                { id = 6569, name = "Oculus Illusions", npc = "Myranda the Hag" },
                { id = 6570, name = "Emberstrife", npc = "Myranda the Hag" },
            },
        },
        {
            chapter = "The Test of Skulls",
            faction = "Horde",
            summary = "Emberstrife, in a den deep in the Wyrmbog of Dustwallow Marsh, won't take you on faith. The test is skulls: one from a champion of each of the blue, green, bronze and red dragonflights.",
            recap = "Emberstrife wanted proof, and dragons keep their proof in skulls. Four of them, one from the champion of each of the other flights: blue up in Winterspring, green in the Swamp of Sorrows, red on the road to Grim Batol, and bronze guarding the Caverns of Time. That's a lot of map for one shopping list, and not one of them went down easy.\n\nI hauled the lot back to the Wyrmbog, still wearing my borrowed face, and came away with a dull old amulet and one large problem. The next step was inside Blackrock Spire, and the disguise wouldn't hold up in there.\n\nThe charade was over. So I went to find Rexxar again, which, as you'll remember, takes a while.",
            quests = {
                { id = 6582, name = "The Test of Skulls, Scryer", npc = "Emberstrife" },
                { id = 6583, name = "The Test of Skulls, Somnus", parallel = true, npc = "Emberstrife" },
                { id = 6584, name = "The Test of Skulls, Chronalis", parallel = true, npc = "Emberstrife" },
                { id = 6585, name = "The Test of Skulls, Axtroz", npc = "Emberstrife" },
                { id = 6601, name = "Ascension...", npc = "Emberstrife" },
            },
        },
        {
            chapter = "Blood of the Black Dragon Champion",
            faction = "Horde",
            summary = "Rexxar, back on the roads of Desolace, knows what the amulet still lacks: the blood of General Drakkisath, champion of the black dragonflight. The general keeps his throne at the top of Blackrock Spire, and a great many guards around it.",
            recap = "Rexxar took one look at the dull amulet and knew what it needed: blood. General Drakkisath's, to be exact, champion of the black dragonflight, who keeps his throne at the very top of Blackrock Spire.\n\nNo disguise this time. We went up the hard way, through everything the Spire had, and into the throne room behind the Halls of Ascension. Drakkisath did not want to part with any of his blood. By the end he'd parted with all of it.\n\nRexxar did the rest and handed me the Drakefire Amulet. Four skulls, twenty eyes, one borrowed face and a dead general went into that thing. If Onyxia ever wonders who's knocking, it's me.",
            quests = {
                { id = 6602, name = "Blood of the Black Dragon Champion", npc = "Rexxar" },
                { id = 7761, name = "Blackhand's Command", location = "Blackrock Mountain, near Blackrock Spire", optional = true, recap = "On the way up to the Spire, a quartermaster was carrying a letter from Rend Blackhand, mostly insults, saying only those with the Mark of Drakkisath could use the Orb of Command into Blackwing Lair, and the general guards the brand himself. With the general past guarding anything, I pressed my hand to the smoldering brand. I didn't flinch, much." },
                { id = 4981, name = "Operative Bijou", npc = "Lexlort", optional = true },
                { id = 4982, name = "Bijou's Belongings", npc = "Bijou", optional = true },
                { id = 4983, name = "Bijou's Reconnaissance Report", npc = "Bijou", optional = true, recap = "Grandmaster Lexlort in Kargath warned me never to trust a goblin, then sent me into the Spire to bring one back: Bijou, an operative who'd been spending Horde gold on side jobs. Bijou had lost her spy gear fleeing an alarm, so I found it, and the reports came back to Kargath without her. Lexlort had to hand it to her: weaseled out again." },
                { id = 4724, name = "The Pack Mistress", npc = "Galamav the Marksman", optional = true, recap = "Galamav the Marksman in Kargath said the Blackrock worgs were no demons, just the brood of Halycon and her mate, so I went into the Spire and killed Halycon. Galamav asked whether I'd survived the rabid pups and Gizrul the Slavener too. I was standing right there, so I let the question answer itself." },
                { id = 4769, name = "Vivian Lagrave and the Darkstone Tablet", npc = "Apothecary Zinge", optional = true, breadcrumbFor = 4768 },
                { id = 4768, name = "The Darkstone Tablet", npc = "Shadowmage Vivian Lagrave", optional = true, recap = "Word came from the Undercity that Shadowmage Vivian Lagrave in Kargath wanted a tablet out of the Spire. Urheld Darkstone, a dwarven alchemist thought mad in his day, had carved his formulae into stone rather than share them, and I found one in what was once the Hall of Fortune. Mad or not, the man kept good notes." },
                { id = 4742, name = "Seal of Ascension", npc = "Vaelan", optional = true },
                { id = 4743, name = "Seal of Ascension", npc = "Vaelan", optional = true, recap = "Vaelan, in the lower Spire, wanted a gemstone from each of three generals and an old seal to set them in. Forging it took black dragonfire, so I wore Emberstrife down in the Wyrmbog and borrowed his mind just long enough to make him breathe on it. That seal is the key to the upper Spire, and not many keys get made that way." },
                { id = 4907, name = "Tinkee Steamboil", npc = "Felnok Steelspring", optional = true, breadcrumbFor = 4734 },
                { id = 4734, name = "Egg Freezing", npc = "Tinkee Steamboil", optional = true },
                { id = 4735, name = "Egg Collection", npc = "Tinkee Steamboil", optional = true, recap = "Tinkee Steamboil at Flame Crest had built a gadget for freezing black dragon eggs solid and needed someone to try it in the Rookery atop the Spire. It worked, so I went back up and collected eight. Freeze them first, Tinkee said, or they might hatch before you get them, which is advice you only need once." },
                { id = 4729, name = "Kibler's Exotic Pets", npc = "Kibler", optional = true, recap = "Kibler at Flame Crest tames exotic beasts for rich clients, and wanted a Bloodaxe worg pup out of the Spire before it grew too old to train. I carried one back in a cage, and Kibler gave me a tame one of my own. It is very ferocious and about the size of a boot." },
                { id = 4862, name = "En-Ay-Es-Tee-Why", npc = "Kibler", optional = true, recap = "Kibler's helper had gone into the Spire for spider eggs weeks before and still wasn't back, so I fetched fifteen myself. Some people, Kibler says, will pay good gold for the most vile of domesticated beasts. I got one free, a little Smolderweb spider, along with a warning not to get bitten." },
                { id = 4866, name = "Mother's Milk", npc = "Ragged John", optional = true, recap = "Ragged John wanted Mother Smolderweb's venom, and not in a jar: he wanted it live, in my veins. So I let the biggest spider in the Spire bite me, walked back feeling awful, and he milked it out of me for the best ale he'd ever brewed. You thought I wanted it for poison, he said, crazy kids." },
                { id = 4867, name = "Urok Doomhowl", npc = "Warosh", optional = true, recap = "Urok Doomhowl had cursed Warosh mute, so all Warosh could do was hand me a scroll that came down to: get my mojo. I got the mojo, and with a voice again Warosh told me I was a fool to think I'd reach the top of the Spire, but that my bravery was beyond question. I've had warmer thanks, and worse." },
                { id = 5160, name = "The Matron Protectorate", npc = "Awbee", optional = true, recap = "Deep in the Spire, Awbee gave me a scale and sent me to Winterspring, where you stand on a cobalt rune in the caves of Mazthoril and end up in front of Haleh. Haleh scried what Awbee had seen in that doomed place. Dragons, I learned, are forbidden to meddle in mortal affairs, unless one of their own starts it." },
                { id = 5047, name = "Pip Quickwit, At Your Service!", npc = "Pip Quickwit", optional = true, recap = "We skinned the Beast in the upper Spire, and out climbed a gnome named Pip Quickwit, in a suit, delighted with how the suit had held up. Pip sent me to Malyfous Darkhammer in Everlook with the news and a glowing lump of the Beast's insides. Malyfous asked if Pip was alive, if the suit worked, and then mostly about the lump." },
                { id = 5127, name = "The Demon Forge", npc = "Lorax", optional = true, recap = "Lorax, out in the snows of Winterspring, had bought the soul of a Spire smith named Goraluk Anvilcrack and sent me to collect it with a fel-soaked pike. Goraluk died, the pike drank him up, and I brought back the breastplate he'd stolen too. Lorax thanked me in rhyme, which somehow made it worse." },
            },
        },
        {
            chapter = "Onyxia's Lair",
            summaryAlliance = "The Drakefire Amulet opens the way into Onyxia's Lair, in the south of Dustwallow Marsh. Behind it waits the dragon who sat at Stormwind's court for years as Lady Prestor. Highlord Bolvar Fordragon would very much like a word with her, or failing that, her head.",
            summaryHorde = "The Drakefire Amulet opens the way into Onyxia's Lair, in the south of Dustwallow Marsh. Behind it waits the brood mother of the black dragonflight, Deathwing's own daughter. Thrall would like all of Orgrimmar to see how that meeting ends.",
            recapAlliance = "The amulet got us through the door of Onyxia's Lair, down in the south of Dustwallow Marsh, and after that it was up to us. Onyxia had spent years in Stormwind as Lady Prestor, at the king's table, steering the kingdom wherever she liked. In her own home she didn't bother with manners. There were whelps. There were a great many whelps.\n\nWe came out with her head, and I carried it to Highlord Bolvar Fordragon in Stormwind Keep. Bolvar had it hung over the city gates, where everyone passing through could see what had been whispering to their king. The whole city stood a little straighter that day.\n\nMajor Mattingly at the gates had a reward for me afterwards, and a speech to go with it: the journey, he said, had only just begun. I've been walking ever since, so he may have had a point.",
            recapHorde = "The amulet got us through the door of Onyxia's Lair, down in the south of Dustwallow Marsh, and after that it was up to us. Onyxia didn't greet us. She breathed on us, which is how dragons say hello. Then came the whelps, a great many whelps, as if she'd been saving them for company.\n\nWe came out with her head, and I carried it to Thrall in Orgrimmar. Thrall sent me on to Overlord Runthak, who had it raised over the Valley of Strength for all to see. Every orc in the city stood a little taller that day, and so did I.\n\nRunthak had a reward for me afterwards, and a speech to go with it: the journey, he said, had only just begun. Easy for him to say. He wasn't the one who carried the head.",
            quests = {
                { id = 7495, name = "Victory for the Alliance", location = "Onyxia's Lair, Dustwallow Marsh", faction = "Alliance", instance = "raid" },
                { id = 7496, name = "Celebrating Good Times", npc = "Highlord Bolvar Fordragon", faction = "Alliance" },
                { id = 7497, name = "The Journey Has Just Begun", npc = "Major Mattingly", faction = "Alliance" },
                { id = 7490, name = "Victory for the Horde", location = "Onyxia's Lair, Dustwallow Marsh", faction = "Horde", instance = "raid" },
                { id = 7491, name = "For All To See", npc = "Thrall", faction = "Horde" },
                { id = 7493, name = "The Journey Has Just Begun", npc = "Overlord Runthak", faction = "Horde" },
                { id = 7509, name = "The Forging of Quel'Serrar", npc = "Lorekeeper Lydros", class = { "WARRIOR", "PALADIN" }, optional = true, instance = "raid", recap = "Lorekeeper Lydros had said the blade wasn't finished until a dragon breathed on it, which is an odd way to temper steel and a very common way to die. So in the middle of all that, I laid Quel'Serrar on the floor of Onyxia's Lair and let her do the forging. Lydros was right. It came out of the fire a proper sword." },
            },
        },
    },
}
